message.content:
{
  "candidate_edge_types": [
    {
      "name": "ATTEMPTS_TO_REPAIR",
      "definition": "A subsequent agent action attempts to resolve a failure, error, or missing requirement identified in an earlier execution step.",
      "source_description": "An earlier observed execution failure, error, or missing prerequisite (e.g., a tool not found).",
      "target_description": "A subsequent agent action intended to resolve that failure or satisfy the missing prerequisite."
    },
    {
      "name": "RETRIES_AFTER_REMEDIATION",
      "definition": "A previously failed operation is re-executed after its underlying cause has been remediated.",
      "source_description": "A successful remediation result that resolves the cause of an earlier failure.",
      "target_description": "A re-execution of the operation that previously failed."
    },
    {
      "name": "USES_PREVIOUS_RESULT_AS_INPUT",
      "definition": "A subsequent action consumes a result or artifact produced by an earlier step as its input.",
      "source_description": "A result or artifact produced by an earlier execution step.",
      "target_description": "A subsequent action that uses that earlier result or artifact as an input."
    },
    {
      "name": "VERIFIES_PREVIOUS_RESULT",
      "definition": "A subsequent action independently checks whether a result or artifact claimed by an earlier step is actually present or as expected.",
      "source_description": "An earlier reported or claimed execution result.",
      "target_description": "A subsequent independent check that confirms or refutes that claimed result."
    },
    {
      "name": "PROBES_ENVIRONMENT_TO_INFORM_ACTION",
      "definition": "An inspection of the execution environment whose outcome determines the selection or configuration of a subsequent action.",
      "source_description": "An environment inspection or probe action that gathers contextual state.",
      "target_description": "A subsequent action selected or configured based on the probe's outcome."
    },
    {
      "name": "TRIGGERS_TASK_COMPLETION",
      "definition": "A verified satisfactory execution outcome leads the agent to conclude that the task is complete.",
      "source_description": "A verified positive execution outcome (e.g., all checks passed and deliverables confirmed).",
      "target_description": "The agent's decision to mark the task as complete."
    }
  ]
}

